def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    def farthest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d > best_d:
                best = (tx, ty)
                best_d = d
        return best

    def step_toward(sx, sy, tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(sx, sy, tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(sx, sy, ox, oy)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = farthest(corners, ox, oy)
        if target is None:
            return step_away(sx, sy, ox, oy)
        return step_toward(sx, sy, target[0], target[1])

