        target = nearest(targets, sx, sy)
        if target is not None:
            return step_toward(sx, sy, target[0], target[1])
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        return step_toward(sx, sy, max(0, w // 2), max(0, h // 2))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return step_toward(sx, sy, target[0], target[1])

    if env == "resource_collection":
        # If no resources are known, bias toward the opponent or center as a fallback.
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        if ox != sx or oy != sy:
            return step_toward(sx, sy, ox, oy)
        return step_toward(sx, sy, max(0, w // 2), max(0, h // 2))

    # Generic fallback: move toward opponent if present, otherwise stay put.
